processor-info.script:

String cmd = input.getText("cmd");


if("PURGE_MENU".equals(cmd))
{
	executeSQL("PURGE_MENU", connection, input, output);

	int deleteNum = 0;
	try
	{
		deleteNum = Integer.parseInt(output.getProperty("rowcount.update:PURGE_MENU"));
	} catch(Exception ex)
	{
	}

	if(deleteNum == 0)
		throw new jdf.framework.core.data.ResourceException("", 20406);

} 
else if("DEPLOY_BOARD_MENU".equals(cmd))
{
	executeSQL("DEPLOY_BOARD_MENU", connection, input, output);
	executeSQL("UPDATE_BOARD_MENU_REL", connection, input, output);
}
else
{
	executeSQL(cmd, connection, input, output);
}
